// Aviso interno de Reymen (alerta o reporte) para el equipo del negocio.
// 1) Verifica la firma de Reymen y que la hora esté dentro de ±5 min (anti-replay).
// 2) Entrega el aviso por CADA destinatario que Reymen decidió (correo y/o WhatsApp). Reymen ya armó el asunto, el
//    texto y el HTML: este flujo NO consulta nada, NO decide a quién avisar y NO lleva datos de ningún cliente.
//    HOY ES UN PROVEEDOR FICTICIO: no manda nada real; reemplaza los bloques CORREO y WHATSAPP por tu SMTP /
//    WhatsApp Business (las credenciales viven en n8n, nunca en Reymen).
// 3) Prepara el callback firmado hacia Reymen: "sent" si todos salieron, "failed" si alguno falló (sin reintentar aquí:
//    los reintentos los controla Reymen, para no duplicar avisos).
// Requiere NODE_FUNCTION_ALLOW_BUILTIN=crypto y N8N_WEBHOOK_SECRET en el entorno de n8n.
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
const item = $input.first();
const headers = item.json.headers || {};
const raw = item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
const ts = String(headers['x-reymen-timestamp'] || '');
const sig = String(headers['x-reymen-signature'] || '');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const age = Math.abs(Date.now() - Number(ts));
if (!secret || !ts || age > 5 * 60 * 1000 || sig.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
  throw new Error('Firma inválida');
}
const msg = JSON.parse(raw);

const recipients = Array.isArray(msg.recipients) ? msg.recipients : [];
const content = msg.content || {};
const errors = [];
for (const r of recipients) {
  try {
    if (r.channel === 'email') {
      // ---- CORREO (ficticio): enviar content.subject / content.html (o content.text) a r.email ----
    } else if (r.channel === 'whatsapp') {
      // ---- WHATSAPP (ficticio): enviar content.text a r.phone ----
    } else {
      throw new Error('canal no soportado');
    }
  } catch (e) {
    errors.push((r.channel || '?') + ': ' + e.message);
  }
}
const result = errors.length === 0 && recipients.length > 0
  ? { status: 'sent', providerMessageId: 'sim_' + msg.execution.id + '_' + msg.execution.attempt }
  : { status: recipients.length === 0 ? 'skipped' : 'failed', providerMessageId: undefined, error: errors.join('; ').slice(0, 400) || 'sin destinatarios' };

const body = JSON.stringify({ executionId: msg.execution.id, token: msg.callback.token, status: result.status, providerMessageId: result.providerMessageId, error: result.error });
const cbTs = String(Date.now());
const cbSig = 'sha256=' + crypto.createHmac('sha256', secret).update(cbTs + '.' + body).digest('hex');
return [{ json: { url: msg.callback.url, body, cbTs, cbSig } }];
